import backtrader as bt


class NVDAMeanReversionStrategy(bt.Strategy):
    params = dict(
        rsi_period=14,
        sma_period=50,
        rsi_entry=31,
        rsi_exit=50,
        hold_days=5,
    )

    def __init__(self):
        self.rsi = bt.indicators.RSI(self.data.close, period=self.p.rsi_period)
        self.sma = bt.indicators.SMA(self.data.close, period=self.p.sma_period)
        self.order = None
        self.bar_executed = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return
        if order.status == order.Completed:
            if order.isbuy():
                self.bar_executed = len(self)
            self.order = None
        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] < self.sma[0] and self.rsi[0] < self.p.rsi_entry:
                self.order = self.buy()
        else:
            if self.rsi[0] > self.p.rsi_exit:
                self.order = self.close()
            elif len(self) - self.bar_executed >= self.p.hold_days:
                self.order = self.close()
